import {protocols as baseProtocols,sources,media,compounds,checked} from './data.js';
import {solutionMass,dilution,masterMix,rpmToRcf,rcfToRpm,insertMass,dnaPmol,thermalSeconds,validateProgram,positive,integer,expandThermal} from './calc.js';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeURL=u=>{try{const x=new URL(u);return ['https:','http:'].includes(x.protocol)?e(x.href):'#';}catch{return '#';}};
const fmt=(n,d=2)=>Number(n).toLocaleString('es-ES',{maximumFractionDigits:d});
const time=s=>s===0?'Sin tiempo fijo':s<60?`${fmt(s)} s`:`${fmt(s/60,1)} min`;
const stamp=d=>new Date(d).toLocaleString('es-ES',{dateStyle:'medium',timeStyle:'short'});
const clone=x=>JSON.parse(JSON.stringify(x));
const key='molab-personal-v1';
const blank=()=>({favorites:[],compoundFavorites:[],mediaFavorites:[],notes:{},configs:{},customCompounds:[],customProtocols:[],runs:[],activeRun:null});
let indexReport=null;
let saved;try{saved={...blank(),...JSON.parse(localStorage.getItem(key)||'{}')};}catch{saved=blank();}
let state={page:'protocols',view:'cards',query:'',category:'Todos',detailTab:'overview',calc:'solutions',compound:'tris',mediaCategory:'Todos',mediaQuery:'',onlyReady:false,personalOnly:false};
let timerInterval,toastTimeout;
function persist(){try{localStorage.setItem(key,JSON.stringify(saved));}catch{toast('No se pudo guardar: almacenamiento del navegador lleno o restringido. Exporta tus datos.');}}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>$('#toast').classList.remove('show'),3300);}
const paths={book:'<path d="M4 5c4-2 6 0 8 1 2-1 4-3 8-1v14c-4-2-6 0-8 1-2-1-4-3-8-1Z"/><path d="M12 6v14"/>',star:'<path d="m12 3 2.8 5.8 6.4.9-4.6 4.5 1.1 6.3-5.7-3-5.7 3 1.1-6.3-4.6-4.5 6.4-.9Z"/>',calc:'<rect x="5" y="3" width="14" height="18" rx="3"/><path d="M8 7h8M8 11h1m6 0h1M8 15h1m6 0h1M8 18h1m6 0h1"/>',flask:'<path d="M9 3h6m-5 0v7L4 19c-1 2 1 2 2 2h12c1 0 3 0 2-2l-6-9V3M8 15h8"/>',note:'<rect x="5" y="3" width="15" height="18" rx="2"/><path d="M9 7h7M9 11h7M9 15h5M3 7h4M3 11h4M3 15h4"/>',globe:'<circle cx="12" cy="12" r="9"/><ellipse cx="12" cy="12" rx="4" ry="9"/><path d="M3 12h18"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4 4"/>',plus:'<path d="M12 5v14M5 12h14"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="2"/><rect x="14" y="3" width="7" height="7" rx="2"/><rect x="3" y="14" width="7" height="7" rx="2"/><rect x="14" y="14" width="7" height="7" rx="2"/>',list:'<path d="M8 6h13M8 12h13M8 18h13M3 6h1M3 12h1M3 18h1"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',check:'<path d="m5 12 4 4L19 6"/>',external:'<path d="M14 3h7v7M21 3l-9 9M10 3H5a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-5"/>',back:'<path d="m14 6-6 6 6 6"/>',thermo:'<path d="M10 14V5a2 2 0 0 1 4 0v9a4 4 0 1 1-4 0Z"/><path d="M12 9v8"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',play:'<path d="m8 4 12 8-12 8Z"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5Z"/>',dna:'<path d="M6 3c0 9 12 9 12 18M18 3c0 9-12 9-12 18M7 6h10M8 9h8M8 15h8M7 18h10"/>',drop:'<path d="M12 3C9 8 5 11 5 15a7 7 0 0 0 14 0c0-4-4-7-7-12Z"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6Z"/><path d="m8 12 3 3 5-6"/>'};
const icon=(n,cls='')=>`<svg class="${cls}" aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">${paths[n]||paths.book}</svg>`;
const navItems=[['protocols','Protocolos','book'],['favorites','Favoritos','star'],['calculators','Cálculos','calc'],['media','Medios','flask'],['notebook','Cuaderno','note'],['sources','Fuentes','globe']];
function allProtocols(){return [...baseProtocols,...saved.customProtocols];}
function allCompounds(){return [...compounds,...saved.customCompounds];}
function vendor(id){return sources.find(s=>s.id===id)||{name:'Mi laboratorio',short:'ML',color:'#6b7fae'};}
function vendorIcon(v){return `<span class="vendor-icon" style="--vendor:${v.color}">${e(v.short)}</span>`;}
function heading(eyebrow,title,subtitle,action=''){return `<div class="page-heading"><div><p class="eyebrow">${eyebrow}</p><h1>${title}</h1><p class="subheading">${subtitle}</p></div>${action}</div>`;}
function empty(title,text,action=''){return `<div class="empty"><h3>${title}</h3><p>${text}</p>${action}</div>`;}
function favoriteButton(id,type='protocol'){const arr=type==='media'?saved.mediaFavorites:saved.favorites;const active=arr.includes(id);return `<button class="icon-button ${active?'saved':''}" data-favorite="${e(id)}" data-type="${type}" aria-label="${active?'Quitar de':'Añadir a'} favoritos: ${e(type==='media'?media.find(m=>m.id===id)?.name:allProtocols().find(p=>p.id===id)?.title)}" aria-pressed="${active}">${icon('star')}</button>`;}
function card(p){const v=vendor(p.manufacturer);return `<article class="protocol-card"><div class="card-top">${vendorIcon(v)}<span class="vendor-name">${e(v.name)}</span>${favoriteButton(p.id)}</div><button class="card-title" data-protocol="${e(p.id)}">${e(p.title)}</button><p class="card-subtitle">${e(p.subtitle)}</p><div class="card-bottom">${p.tags.slice(0,2).map(t=>`<span class="tag ${t.includes('PCR')?'blue':''}">${e(t)}</span>`).join('')}<span class="card-time">${icon(p.status==='reference'?'external':'clock')}${p.status==='reference'?'Referencia':p.duration||'Personal'}</span></div></article>`;}
function nav(){ $('#nav').innerHTML=navItems.map(([id,name,ic])=>`<button class="nav-item ${state.page===id||state.page==='detail'&&id==='protocols'||state.page==='run'&&id==='notebook'?'active':''}" data-nav="${id}">${icon(ic)}<span>${name}</span>${id==='favorites'&&saved.favorites.length?`<span class="count">${saved.favorites.length}</span>`:''}</button>`).join(''); }
function go(page){if(page==='run'){location.hash='run';return;} if(page==='protocols')state.personalOnly=false;location.hash=page;}
function readRoute(){const parts=location.hash.slice(1).split('/');state.page=parts[0]||'protocols';state.id=parts[1];if(!['protocols','favorites','calculators','media','notebook','sources','detail','run'].includes(state.page))state.page='protocols';render();}
function render(){nav();const label=navItems.find(n=>n[0]===state.page)?.[1]||'Protocolo';$('#breadcrumb').textContent=`Biblioteca / ${label}`;const views={protocols:library,favorites:favorites,calculators:calculators,media:mediaPage,notebook:notebook,sources:sourcesPage,detail:detail,run:runPage};$('#app').innerHTML=views[state.page]();bindView();if(state.page==='run')startTick();else clearInterval(timerInterval);}
function quickRail(){return `<aside class="right-rail"><section class="side-panel"><p class="panel-label">A MANO, SIEMPRE</p><h2>Cálculos rápidos</h2>${[['solutions','Soluciones','Masa, volumen y concentración','flask'],['mastermix','Master mix','Prepara todas tus reacciones','dna'],['dilutions','Diluciones','De tu stock a la concentración final','drop']].map(([id,title,sub,ic])=>`<button class="quick-link" data-calc="${id}"><span class="quick-icon">${icon(ic)}</span><span><strong>${title}</strong><small>${sub}</small></span></button>`).join('')}</section><section class="side-panel"><p class="panel-label">TU SELECCIÓN</p><h2>Favoritos</h2>${saved.favorites.length?allProtocols().filter(p=>saved.favorites.includes(p.id)).slice(0,3).map(p=>`<button class="quick-link" data-protocol="${p.id}"><span class="quick-icon">${icon('star')}</span><span><strong>${e(p.title)}</strong><small>${e(vendor(p.manufacturer).name)}</small></span></button>`).join(''):'<p class="help">Guarda con la estrella los protocolos que usas a menudo.</p>'}<button class="text-button" data-nav="favorites" style="margin-top:15px">Ver mi selección</button></section><section class="library-note">${icon('shield')}<h3>De la fuente a tu mesa</h3><p>Cada ficha conserva su documento original y su estado de revisión.</p><a class="small-link" href="#sources">Explorar las fuentes</a></section></aside>`;}
function normalized(t){return String(t).normalize('NFD').replace(/\p{Diacritic}/gu,'').toLowerCase();}
function library(){const all=allProtocols(),cats=[...new Set(all.map(p=>p.category))];const query=normalized(state.query);let shown=all.filter(p=>(state.category==='Todos'||p.category===state.category)&&(!state.onlyReady||p.status!=='reference')&&(!state.personalOnly||p.manufacturer==='personal')&&normalized(`${p.title} ${p.subtitle} ${p.tags.join(' ')} ${vendor(p.manufacturer).name}`).includes(query));
 let results=state.view==='cards'?`<div class="protocol-grid">${shown.map(card).join('')||empty('No hay coincidencias','Prueba con otra técnica, fabricante o palabra.')}</div>`:`<div class="vendor-tree">${[...sources,{id:'personal',name:'Mi laboratorio',short:'ML',color:'#6b7fae'}].filter(v=>shown.some(p=>p.manufacturer===v.id)).map(v=>`<details ${query?'open':''}><summary>${vendorIcon(v)}<span class="tree-name">${e(v.name)}</span><small>${shown.filter(p=>p.manufacturer===v.id).length} fichas</small></summary><div class="nested">${cats.filter(c=>shown.some(p=>p.manufacturer===v.id&&p.category===c)).map(c=>`<details ${query?'open':''}><summary><span class="tree-name">${e(c)}</span><small>${shown.filter(p=>p.manufacturer===v.id&&p.category===c).length} protocolos</small></summary><div class="protocol-grid">${shown.filter(p=>p.manufacturer===v.id&&p.category===c).map(card).join('')}</div></details>`).join('')}</div></details>`).join('')||empty('No hay coincidencias','Cambia los filtros.')}</div>`;
 return heading('LA BIBLIOTECA DE TU LABORATORIO','Protocolos','Encuentra, prepara y sigue tu próximo experimento.',`<button class="button" id="new-protocol">${icon('plus')}Nuevo protocolo</button>`)+`<div class="stat-strip"><div class="stat"><strong>${all.length}</strong><span>fichas indexadas</span></div><div class="stat"><strong>${all.filter(p=>p.status==='reviewed').length}</strong><span>con pasos revisados</span></div><div class="stat"><strong>${sources.length}</strong><span>fuentes oficiales</span></div></div><div class="search-row"><div class="search-wrap">${icon('search')}<input class="search-input" id="protocol-search" aria-label="Buscar protocolos" placeholder="Busca un protocolo, técnica o fabricante…" value="${e(state.query)}"><span class="search-shortcut">⌘ K</span></div><div class="toggle" aria-label="Vista de catálogo"><button data-view="cards" class="${state.view==='cards'?'selected':''}">${icon('grid')}Todos</button><button data-view="vendors" class="${state.view==='vendors'?'selected':''}">${icon('list')}Por casa</button></div></div><div class="category-row">${['Todos',...cats].map(c=>`<button class="chip ${state.category===c?'active':''}" data-category="${e(c)}">${e(c)}</button>`).join('')}</div><div class="work-grid"><section><div class="section-heading"><h2>${state.category==='Todos'?'Explora la biblioteca':e(state.category)}</h2><label class="checkbox-field"><input type="checkbox" id="ready-filter" ${state.onlyReady?'checked':''}>Solo con pasos</label></div>${results}</section>${quickRail()}</div>`;}
function favorites(){const ps=allProtocols().filter(p=>saved.favorites.includes(p.id)),ms=media.filter(m=>saved.mediaFavorites.includes(m.id));return heading('GUARDADO PARA TI','Tus favoritos','Los protocolos, medios y compuestos que quieres tener cerca.')+`<div class="section-heading"><h2>Protocolos</h2><span>${ps.length} guardados</span></div><div class="protocol-grid">${ps.map(card).join('')||empty('Tu biblioteca personal empieza aquí','Marca una estrella en cualquier protocolo.',`<button class="button" data-nav="protocols">Explorar protocolos</button>`)}</div><div class="section-heading" style="margin-top:30px"><h2>Compuestos</h2><span>${saved.compoundFavorites.length} guardados</span></div><div class="panel">${compoundFavorites()}</div><div class="section-heading" style="margin-top:30px"><h2>Medios de cultivo</h2><span>${ms.length} guardados</span></div><div class="media-grid">${ms.map(mediaCard).join('')||empty('Medios de cultivo favoritos','Guarda tus medios desde la sección Medios.')}</div>`;}
function compoundFavorites(){let cs=allCompounds().filter(c=>saved.compoundFavorites.includes(c.id));return cs.length?`<div class="compound-list">${cs.map(c=>`<div class="compound-row"><span class="quick-icon">${icon('flask')}</span><button class="compound-select" data-compound="${e(c.id)}"><strong>${e(c.name)}</strong><small>${e(c.formula)} · ${fmt(c.mw)} g/mol</small></button><button class="icon-button saved" data-compound-star="${e(c.id)}" aria-label="Quitar ${e(c.name)} de favoritos">${icon('star')}</button></div>`).join('')}</div>`:'<p class="help">Guarda un compuesto desde la calculadora de soluciones. También puedes añadir uno con su forma química exacta.</p>';}
function getProtocol(){return allProtocols().find(p=>p.id===state.id);}
function initialConfig(p){return {reactions:8,controls:1,excess:10,volume:p.volume||25,components:clone(p.components||[]),cycles:p.cycles||1,thermal:clone(p.thermal||[]),steps:clone(p.steps),edited:false};}
function configFor(p){return saved.configs[p.id]||initialConfig(p);}
function status(p){return p.status==='reviewed'?`${icon('check')} Parámetros revisados desde PDF`:p.status==='personal'?'Protocolo personal · revisión propia':'Referencia · pendiente de estructurar';}
function detail(){const p=getProtocol();if(!p)return empty('Protocolo no encontrado','Vuelve a la biblioteca.',`<button class="button" data-nav="protocols">Volver</button>`);const v=vendor(p.manufacturer);let content;
 if(state.detailTab==='config')content=configView(p);
 else if(state.detailTab==='notes')content=`<section class="panel"><h2>Mis notas y modificaciones</h2><p>Guarda tu experiencia sin alterar el documento original.</p><label class="field">Notas del protocolo<textarea id="protocol-note" placeholder="Lote, condiciones probadas, resultados, cambios…">${e(saved.notes[p.id]||'')}</textarea></label><div class="button-row" style="margin-top:18px"><button class="button primary" id="save-note">Guardar notas</button><button class="button" data-print>Imprimir ficha</button></div><p class="help">Las notas son privadas en este navegador. Exporta una copia para llevarlas a otro dispositivo.</p></section>`;
 else if(state.detailTab==='tips')content=`<section class="panel"><h2>Recomendaciones y evidencia</h2>${p.tips.length?p.tips.map(t=>`<div class="evidence">${icon(t.kind==='Paper'?'book':'spark')}<div><p>${e(t.text)}</p><a target="_blank" rel="noopener noreferrer" href="${safeURL(t.url)}">${e(t.label)} · ${t.kind||'Fabricante'}</a></div></div>`).join(''):empty('Sin recomendaciones revisadas','Consulta la fuente oficial. Puedes guardar otras referencias en tus notas.')}<p class="help">Los consejos del fabricante y los artículos se identifican por separado. No se han añadido consejos de redes sociales sin revisar.</p></section>`;
 else content=`<div class="two-col"><section class="panel"><h2>Acerca de este protocolo</h2><p>${e(p.description)}</p><h2>Cómo funciona</h2><p>${e(p.mechanism)}</p>${p.assumptions?`<div class="note-banner"><strong>Antes de preparar</strong><br>${e(p.assumptions)}</div>`:''}<div class="source-box"><strong>${e(p.version)} · páginas ${e(p.pages)}</strong>Comprobado el ${checked.split('-').reverse().join('/')}<br>${p.source?`<a href="${safeURL(p.source)}" target="_blank" rel="noopener noreferrer">Abrir ${p.sourceType||'fuente'} original ${icon('external')}</a>`:'Fuente personal'}<br>Resumen en español; consulta el documento completo.</div></section><section class="panel"><div class="section-heading"><h2>${p.steps.length?'El recorrido':'Documento de referencia'}</h2>${p.steps.length?`<span>${configFor(p).steps.length} pasos</span>`:''}</div>${p.steps.length?configFor(p).steps.map((s,i)=>`<div class="step-preview"><span class="step-num">${i+1}</span><div><h3>${e(s.title)}</h3><p>${e(s.text)}</p>${s.seconds||s.conditions?`<div class="step-meta">${e(s.conditions)}${s.seconds?' · '+time(s.seconds):''}</div>`:''}</div></div>`).join(''):`<p>Esta ficha enlaza la fuente original. Los pasos y cantidades todavía no están revisados para ejecución en Molab.</p><div class="button-row"><a class="button" href="${safeURL(p.source)}" target="_blank" rel="noopener noreferrer">Consultar fuente ${icon('external')}</a><button class="button" id="adapt-protocol">Crear adaptación personal</button></div>`}</section></div>`;
 return `<button class="back-link" data-nav="protocols">${icon('back')}Biblioteca de protocolos</button><div class="detail-heading"><h1>${e(p.title)}</h1><div class="detail-meta">${vendorIcon(v)}<span>${e(v.name)}</span><span class="status-label ${p.status==='reviewed'?'reviewed':''}">${status(p)}</span>${favoriteButton(p.id)}</div></div><div class="button-row">${p.steps.length?`<button class="button primary" data-tab="config">${icon('calc')}Configurar experimento</button>`:''}<button class="button" data-tab="notes">${icon('note')}Mis notas</button>${p.source?`<a class="button" href="${safeURL(p.source)}" rel="noopener noreferrer" target="_blank">${icon('external')}Fuente original</a>`:''}</div><div class="tabs" role="tablist">${[['overview','Descripción y pasos'],...(p.steps.length?[['config','Configuración']]:[]),['notes','Notas'],['tips','Recomendaciones']].map(([id,t])=>`<button class="tab ${state.detailTab===id?'selected':''}" role="tab" aria-selected="${state.detailTab===id}" data-tab="${id}">${t}</button>`).join('')}</div>${content}`;}
function configView(p){const c=configFor(p);let result='';if(c.components.length){try{result=mixTable(masterMix(c,c.components));}catch(err){result=`<p class="error">${e(err.message)}</p>`;}}
 return `<div class="two-col"><section class="panel"><h2>Prepara tus reacciones</h2>${p.assumptions?`<p>${e(p.assumptions)}</p>`:''}<div class="form-grid"><label class="field">${p.components?'Reacciones de muestra':'Número de muestras'}<input data-config="reactions" type="number" min="1" step="1" value="${c.reactions}"></label>${p.components?`<label class="field">Controles adicionales<input data-config="controls" type="number" min="0" step="1" value="${c.controls}"></label><label class="field">Exceso de mezcla (%)<input data-config="excess" type="number" min="0" max="100" value="${c.excess}"></label><label class="field">Volumen / reacción (µL)<input data-config="volume" type="number" min="0.1" step="0.1" value="${c.volume}"></label>`:''}</div>${c.components.length?`<div class="table-scroll"><table><thead><tr><th>Reactivo</th><th>µL / reacción</th><th>Mezcla común</th></tr></thead><tbody>${c.components.map((r,i)=>`<tr><td>${e(r.name)}</td><td><input aria-label="${e(r.name)} en µL" data-component="${i}" type="number" min="0" step="0.01" value="${r.volume}"></td><td>${r.template?'Añadir por tubo':'Sí'}</td></tr>`).join('')}</tbody></table></div><div id="mix-result">${result}</div><p class="help">El DNA se calcula aparte sin exceso. Para NTC sustituye su volumen por agua. El exceso se aplica a la mezcla común, con los controles incluidos.</p><button class="button small" id="export-mix" style="margin-top:15px">${icon('download')}Exportar tabla CSV</button>`:'<p class="help">Los volúmenes de estos pasos corresponden a cada muestra o membrana. Esta ficha no tiene una mezcla común escalable.</p>'}<div class="button-row" style="margin-top:22px"><button class="button" id="edit-steps">Editar pasos y condiciones</button><button class="button small" id="add-thermal">Añadir fase térmica</button><button class="button small" id="reset-config">Restaurar valores</button></div></section><section class="panel"><h2>${c.thermal.length?'Programa del termociclador':'Pasos y condiciones'}</h2>${c.thermal.length?`<div id="thermal-chart">${thermalChart(c.thermal)}</div><label class="field">Ciclos de amplificación<input type="number" min="1" max="100" step="1" value="${c.cycles}" data-config="cycles"></label><div class="program-row program-header"><span>Fase</span><span>°C</span><span>Segundos</span><span>Ciclo</span></div>${c.thermal.map((t,i)=>`<div class="program-row"><span>${e(t.label)}</span><input type="number" min="0" max="110" step="0.1" value="${t.temp}" data-thermal="${i}" data-field="temp" aria-label="Temperatura ${e(t.label)}"><input type="number" min="0" value="${t.seconds}" data-thermal="${i}" data-field="seconds" aria-label="Segundos ${e(t.label)}"><input type="checkbox" ${t.repeat?'checked':''} data-thermal="${i}" data-field="repeat" aria-label="Repetir ${e(t.label)} en cada ciclo"></div>`).join('')}<p class="help" id="thermal-duration">${thermalDescription(c)}</p>`:c.steps.slice(0,6).map((s,i)=>`<div class="step-preview"><span class="step-num">${i+1}</span><div><h3>${e(s.title)}</h3><p>${e(s.conditions)}${s.seconds?' · '+time(s.seconds):''}</p></div></div>`).join('')}<div class="note-banner">${c.edited?'Configuración modificada por ti.':'Valores de partida: revisa los parámetros de tu ensayo.'}<br>Start inicia la guía y sus cronómetros. El equipo se programa por separado.</div><label class="field">Identificador del experimento<input id="experiment-name" placeholder="Ej.: PCR gen A · lote 12"></label><div id="config-error"></div><button class="button primary" id="start-protocol" style="margin-top:20px;width:100%">${icon('play')}Start · comenzar protocolo</button></section></div>`;}
function thermalDescription(c){try{return `${c.cycles} ciclos · ${time(thermalSeconds(c.thermal,c.cycles))} de incubación; no incluye rampas ni conservación indefinida. 0 s significa sin duración fija.`;}catch{return 'Revisa los tiempos y el número de ciclos.';}}
function mixTable(m){return `<div class="table-scroll"><table><thead><tr><th>Reactivo</th><th>Por tubo</th><th>Total (µL)</th></tr></thead><tbody>${m.rows.map(r=>`<tr><td>${e(r.name)}${r.template?' <span class="tag">Aparte</span>':''}</td><td>${fmt(r.per)} µL</td><td>${fmt(r.total)}</td></tr>`).join('')}<tr class="total-row"><td>Mezcla común / tubo</td><td>${fmt(m.mixPer)} µL</td><td>${fmt(m.mixPer*m.factor)}</td></tr></tbody></table></div><p class="help">${m.count} tubos · ${fmt(m.factor,2)} equivalentes con exceso · ${fmt(m.volume)} µL finales por tubo.</p>`;}
function thermalChart(program){if(!program.length)return '';let pts=[],width=640,height=180,left=38,right=620,bottom=151;let step=(right-left)/program.length;program.forEach((p,i)=>{const y=bottom-Number(p.temp)/110*120;pts.push(`${left+i*step},${y}`,`${left+(i+1)*step},${y}`);});return `<svg class="thermal-chart" viewBox="0 0 ${width} ${height}" role="img" aria-label="Programa térmico: ${e(program.map(t=>`${t.label} ${t.temp} grados ${t.seconds} segundos${t.repeat?' por ciclo':''}`).join('; '))}"><defs><linearGradient id="area" x2="0" y2="1"><stop stop-color="#6c8ffa" stop-opacity=".18"/><stop offset="1" stop-color="#6c8ffa" stop-opacity="0"/></linearGradient></defs>${[0,25,50,75,100].map(t=>`<line class="grid" x1="${left}" x2="${right}" y1="${bottom-t/110*120}" y2="${bottom-t/110*120}"/><text x="0" y="${bottom-t/110*120+4}">${t}°</text>`).join('')}<polygon fill="url(#area)" points="${left},${bottom} ${pts.join(' ')} ${right},${bottom}"/><polyline class="curve" points="${pts.join(' ')}"/>${program.map((p,i)=>`<text x="${left+step*(i+.5)}" y="175" text-anchor="middle">${i+1}${p.repeat?' ↻':''}</text>`).join('')}</svg>`;}
function calculators(){const tabs=[['solutions','Soluciones'],['dilutions','Diluciones'],['mastermix','Master mix'],['cloning','Cloning'],['centrifuge','Centrífuga'],['qpcr','qPCR']];let content={solutions:solutionsView,dilutions:dilutionsView,mastermix:mastermixView,cloning:cloningView,centrifuge:centrifugeView,qpcr:qpcrView}[state.calc]?.()||solutionsView();return heading('MENOS CUENTAS. MÁS CIENCIA.','Cálculos de laboratorio','Unidades claras, resultados reproducibles y tus reactivos a mano.')+`<div class="category-row calc-tabs">${tabs.map(([id,t])=>`<button class="chip ${state.calc===id?'active':''}" data-calc="${id}">${t}</button>`).join('')}</div>${content}`;}
function options(items,selected){return items.map(v=>`<option value="${e(v)}" ${selected===v?'selected':''}>${e(v)}</option>`).join('');}
function numberField(label,id,value,min=0.001,step='any'){return `<label class="field">${label}<input id="${id}" type="number" min="${min}" step="${step}" value="${value}"></label>`;}
function selectField(label,id,items,val){return `<label class="field">${label}<select id="${id}">${options(items,val)}</select></label>`;}
function solutionsView(){const cs=allCompounds();const c=cs.find(c=>c.id===state.compound)||cs[0];return `<div class="two-col"><section class="panel"><div class="section-heading"><h2>Preparar una solución</h2><button class="icon-button ${saved.compoundFavorites.includes(c.id)?'saved':''}" id="save-compound" aria-label="Guardar compuesto en favoritos">${icon('star')}</button></div><div class="form-grid"><label class="field full">Compuesto<select id="compound-select">${cs.map(x=>`<option value="${e(x.id)}" ${x.id===c.id?'selected':''}>${e(x.name)} · ${e(x.formula)}</option>`).join('')}</select></label>${numberField('Masa molecular (g/mol)','mw',c.mw)}${numberField('Pureza (%)','purity',100)}${numberField('Concentración final','concentration',100)}${selectField('Unidad de concentración','concentration-unit',['M','mM','µM','nM','g/L','% m/v'],'mM')}${numberField('Volumen final','solution-volume',100)}${selectField('Unidad de volumen','volume-unit',['L','mL','µL'],'mL')}</div><div id="calc-result" aria-live="polite"></div><p class="help">Comprueba la forma química e hidratación en la etiqueta o certificado. Ajustar pH o disolver no cambia el volumen final requerido. Soluciones en % v/v: usa la calculadora de diluciones con unidades iguales.</p><div class="button-row" style="margin-top:18px"><button class="button" id="new-compound">${icon('plus')}Añadir compuesto</button><button class="button" id="update-compound">Guardar masa editada</button><button class="button" id="record-calc">${icon('note')}Guardar cálculo</button></div></section><section class="panel"><h2>Compuestos favoritos</h2>${compoundFavorites()}<div class="note-banner"><strong>Una receta, una forma química</strong><br>EDTA disódico dihidrato y EDTA anhidro tienen distinta masa molecular. Tus compuestos personalizados guardan el nombre y la masa que indiques.</div><h2>La cuenta</h2><p>m = C × V × MM ÷ fracción de pureza</p><p class="help">C en mol/L, V en litros y MM en g/mol. Para g/L y % m/v se utiliza directamente la concentración en masa.</p></section></div>`;}
function dilutionsView(){return `<div class="two-col"><section class="panel"><h2>Diluir un stock</h2><p>Utiliza la misma unidad de concentración para C₁ y C₂.</p><div class="form-grid">${numberField('Concentración stock · C₁','c1',100)}${numberField('Concentración final · C₂','c2',10)}${selectField('Unidad de concentración','dilution-unit',['M','mM','µM','nM','mg/mL','g/L','% v/v'],'mM')}${numberField('Volumen final · V₂','v2',100)}${selectField('Unidad de volumen','dilution-volume-unit',['mL','µL','L'],'mL')}</div><div id="calc-result" aria-live="polite"></div><button class="button" id="record-calc" style="margin-top:18px">${icon('note')}Guardar cálculo</button></section><section class="panel"><h2>C₁V₁ = C₂V₂</h2><p>Calcula cuánto stock necesitas y cuánto diluyente añadir hasta el volumen final.</p><div class="note-banner">Si C₂ supera C₁, una dilución no puede producir la concentración solicitada.</div></section></div>`;}
function mastermixView(){return `<div class="two-col"><section class="panel"><h2>Mezclas basadas en protocolo</h2><p>Elige la mezcla. Se abrirán su receta, controles y programa.</p><div class="tools-list">${allProtocols().filter(p=>p.components?.length).map(p=>`<button class="button" data-mix-protocol="${p.id}"><strong>${e(p.title)}</strong><small>${p.volume} µL · ${e(vendor(p.manufacturer).name)}</small></button>`).join('')}</div></section><section class="panel"><h2>Tu propia master mix</h2><p>Define una mezcla con reactivos, volumen por tubo y exceso de pipeteo. Guárdala como protocolo personal para reutilizarla.</p><button class="button primary" id="new-protocol">${icon('plus')}Crear mezcla personal</button><div class="note-banner">El componente marcado como molde se añade por tubo. Los demás forman la mezcla común.</div></section></div>`;}
function cloningView(){return `<div class="two-col"><section class="panel"><h2>Ratio molar vector : inserto</h2><div class="form-grid">${numberField('Masa vector (ng)','vector-mass',50)}${numberField('Longitud vector (bp)','vector-bp',5000,1,1)}${numberField('Longitud inserto (bp)','insert-bp',1000,1,1)}${numberField('Ratio inserto / vector','insert-ratio',3)}${numberField('Stock inserto (ng/µL)','insert-stock',20)}</div><div id="calc-result" aria-live="polite"></div><button class="button" id="record-calc" style="margin-top:18px">Guardar cálculo</button></section><section class="panel"><h2>Cantidades molares de DNA</h2><p>pmol = ng × 1.000 / (bp × 650)</p><p class="help">Aproximación para DNA de doble hebra con 650 g/mol por par de bases, utilizada por NEBuilder. El ratio depende de tu método de ensamblaje.</p><a class="small-link" href="${safeURL(baseProtocols.find(p=>p.id==='hifi').source)}" target="_blank" rel="noopener noreferrer">Fuente: NEBuilder · p. 8</a><div class="note-banner">Para NEBuilder, comprueba el rango de cantidad total de DNA y el número de fragmentos antes del montaje.</div></section></div>`;}
function centrifugeView(){return `<div class="two-col"><section class="panel"><h2>RPM y fuerza centrífuga</h2><div class="form-grid">${selectField('Convertir','centrifuge-mode',['RPM → × g','× g → RPM'],'RPM → × g')}${numberField('Radio efectivo del rotor (cm)','radius',8)}${numberField('Valor de entrada','centrifuge-value',12000,1)}</div><div id="calc-result" aria-live="polite"></div><button class="button" id="record-calc" style="margin-top:18px">Guardar cálculo</button></section><section class="panel"><h2>Cada rotor tiene su radio</h2><p>RCF = 1,118 × 10⁻⁵ × r(cm) × RPM²</p><p class="help">Introduce el radio correspondiente a la posición de la muestra según el manual del rotor. No intercambies RPM y × g entre equipos.</p></section></div>`;}
function qpcrView(){return `<div class="two-col"><section class="panel"><h2>Expresión relativa · ΔΔCt</h2><div class="form-grid">${numberField('Ct diana · muestra','ct-target',24,0)}${numberField('Ct referencia · muestra','ct-ref',20,0)}${numberField('Ct diana · calibrador','ct-target-control',26,0)}${numberField('Ct referencia · calibrador','ct-ref-control',20,0)}</div><div id="calc-result" aria-live="polite"></div><button class="button" id="record-calc" style="margin-top:18px">Guardar cálculo</button></section><section class="panel"><h2>2⁻ΔΔCt</h2><p>Supone eficiencias similares, cercanas al 100 %, y una referencia validada. Utiliza promedios de réplicas revisadas; los Ct no detectados no se sustituyen por cero.</p><a href="https://doi.org/10.1006/meth.2001.1262" target="_blank" rel="noopener noreferrer" class="small-link">Livak & Schmittgen, 2001</a><div class="note-banner">Este cálculo no incluye ajuste por eficiencia ni análisis estadístico.</div></section></div>`;}
let lastCalc;
function updateCalc(){if(!$('#calc-result'))return;try{const val=id=>$('#'+id).value;let title,num,unit,body,input;
 if(state.calc==='solutions'){input={concentration:val('concentration'),unit:val('concentration-unit'),volume:val('solution-volume'),volumeUnit:val('volume-unit'),mw:val('mw'),purity:val('purity')};const mass=solutionMass(input);const inMg=mass<1;title='Cantidad a pesar';num=fmt(inMg?mass*1000:mass,5);unit=inMg?'mg':'g';const compound=allCompounds().find(c=>c.id===val('compound-select'));body=`${e(compound?.name)} · ${e(input.concentration)} ${e(input.unit)} · ${e(input.volume)} ${e(input.volumeUnit)} finales.<br>Disuelve y completa hasta el volumen final. MM ${e(input.mw)} g/mol · pureza ${e(input.purity)} %.`;}
 else if(state.calc==='dilutions'){input={c1:val('c1'),c2:val('c2'),v2:val('v2'),concentrationUnit:val('dilution-unit'),volumeUnit:val('dilution-volume-unit')};const d=dilution(input.c1,input.c2,input.v2);title='Volumen de stock';num=fmt(d.stock,5);unit=input.volumeUnit;body=`Añade ${fmt(d.solvent,5)} ${e(unit)} de diluyente.<br>Volumen final: ${fmt(input.v2)} ${e(unit)} · ${e(input.c2)} ${e(input.concentrationUnit)}.`;}
 else if(state.calc==='cloning'){input={vectorMass:val('vector-mass'),vectorBp:val('vector-bp'),insertBp:val('insert-bp'),ratio:val('insert-ratio'),stock:val('insert-stock')};const mass=insertMass(input.vectorMass,input.vectorBp,input.insertBp,input.ratio);title='Masa de inserto';num=fmt(mass,4);unit='ng';body=`Pipetea ${fmt(mass/positive(input.stock,'Stock'),4)} µL de inserto.<br>Vector: ${fmt(dnaPmol(input.vectorMass,input.vectorBp),5)} pmol · Inserto: ${fmt(dnaPmol(mass,input.insertBp),5)} pmol.<br>Ratio vector:inserto 1:${e(input.ratio)}.`;}
 else if(state.calc==='centrifuge'){input={mode:val('centrifuge-mode'),radius:val('radius'),value:val('centrifuge-value')};const rpm=input.mode.startsWith('RPM');title=rpm?'Fuerza centrífuga relativa':'Velocidad de rotación';num=fmt(rpm?rpmToRcf(input.radius,input.value):rcfToRpm(input.radius,input.value),0);unit=rpm?'× g':'RPM';body=`Radio: ${e(input.radius)} cm · Entrada: ${e(input.value)} ${rpm?'RPM':'× g'}.`;} 
 else if(state.calc==='qpcr'){input={target:val('ct-target'),ref:val('ct-ref'),targetControl:val('ct-target-control'),refControl:val('ct-ref-control')};Object.values(input).forEach(v=>positive(v,'Ct'));const d=Number(input.target)-Number(input.ref),dc=Number(input.targetControl)-Number(input.refControl),dd=d-dc,fold=2**(-dd);if(!Number.isFinite(fold))throw new Error('Valores Ct fuera del rango calculable.');title='Expresión relativa al calibrador';num=fmt(fold,5);unit='veces';body=`ΔCt muestra: ${fmt(d)} · ΔCt calibrador: ${fmt(dc)}<br>ΔΔCt: ${fmt(dd)} · Eficiencia asumida: 100 %.`;}
 else return;$('#calc-result').innerHTML=`<div class="result"><div class="result-label">${title}</div><div class="result-number">${num}<small>${unit}</small></div><p>${body}</p></div>`;lastCalc={title,input,result:`${num} ${unit}`,description:body.replace(/<br>/g,'\n').replace(/<[^>]*>/g,''),kind:state.calc};
 }catch(err){$('#calc-result').innerHTML=`<p class="error">${e(err.message)}</p>`;lastCalc=null;}}
function mediaCard(m){const v=vendor(m.manufacturer);return `<article class="protocol-card media-card"><div class="card-top">${vendorIcon(v)}<span class="vendor-name">${e(m.category)}</span>${favoriteButton(m.id,'media')}</div><h3>${e(m.name)}</h3><p>${e(m.description)}</p><div class="media-dose">${m.grams?`${fmt(m.grams)} g/L`:'Consultar formulación'} · ${e(m.format)}</div><div class="button-row"><button class="button small" data-medium="${m.id}">${m.grams?'Calcular':'Ver ficha'}</button><a class="icon-button" aria-label="Fuente de ${e(m.name)}" target="_blank" rel="noopener noreferrer" href="${safeURL(m.source)}">${icon('external')}</a></div></article>`;}
function mediaPage(){const query=normalized(state.mediaQuery),shown=media.filter(m=>(state.mediaCategory==='Todos'||m.category===state.mediaCategory)&&normalized(m.name+' '+m.description).includes(query));return heading('DEL MEDIO AL CULTIVO','Medios de cultivo','Formulaciones identificadas por producto y fuente oficial.')+`<div class="search-wrap">${icon('search')}<input id="media-search" class="search-input" value="${e(state.mediaQuery)}" placeholder="Busca un medio o formulación…" aria-label="Buscar medios"></div><div class="category-row" style="margin-top:20px">${['Todos','Microbiológicos','Hongos','Plantas','Animales / humanas'].map(c=>`<button class="chip ${state.mediaCategory===c?'active':''}" data-media-category="${e(c)}">${e(c)}</button>`).join('')}</div><div class="section-heading"><h2>${e(state.mediaCategory==='Todos'?'Biblioteca de medios':state.mediaCategory)}</h2><span>${shown.length} referencias</span></div><div class="media-grid">${shown.map(mediaCard).join('')||empty('No hay coincidencias','Prueba otro término.')}</div><div class="note-banner">Las dosis calculables corresponden al polvo comercial indicado. Las variantes, suplementos y medios sin dosis revisada enlazan su formulación; no se sustituye una receta por otra.</div>`;}
function mediumDialog(id){const m=media.find(m=>m.id===id);showDialog(`<h2>${e(m.name)}</h2><p class="help" style="margin:12px 0 20px">${e(m.description)}</p>${m.grams?`<div class="form-grid">${numberField('Volumen final (mL)','medium-volume',500)}${numberField('Dosis del producto (g/L)','medium-dose',m.grams)}</div><div id="medium-result" aria-live="polite"></div>`:''}<div class="note-banner">${e(m.preparation)}</div><a class="button" href="${safeURL(m.source)}" target="_blank" rel="noopener noreferrer">Abrir formulación oficial ${icon('external')}</a><label class="field" style="margin-top:20px">Mis notas sobre este medio<textarea id="medium-notes">${e(saved.notes['media:'+id]||'')}</textarea></label><div class="modal-footer"><button class="button primary" id="save-medium">Guardar notas</button></div>`);if(m.grams){const calc=()=>{try{const mass=positive($('#medium-volume').value,'Volumen')/1000*positive($('#medium-dose').value,'Dosis');$('#medium-result').innerHTML=`<div class="result"><div class="result-label">Polvo comercial a pesar</div><div class="result-number">${fmt(mass,4)}<small>g</small></div><p>Completa hasta ${e($('#medium-volume').value)} mL finales.</p></div>`;}catch(err){$('#medium-result').innerHTML=`<p class="error">${e(err.message)}</p>`;}};$('#medium-volume').oninput=calc;$('#medium-dose').oninput=calc;calc();}$('#save-medium').onclick=()=>{saved.notes['media:'+id]=$('#medium-notes').value;persist();toast('Notas del medio guardadas.');$('#modal').close();};}
function notebook(){const entries=Object.entries(saved.notes).filter(([,t])=>t.trim());return heading('TU MEMORIA EXPERIMENTAL','Cuaderno de laboratorio','Configuraciones, resultados y observaciones que no quieres perder.',`<button class="button" data-print>${icon('download')}Imprimir</button>`)+`<div class="button-row" style="margin-bottom:22px"><button class="button" data-export-data>Exportar copia personal</button><button class="button" data-import-data>Importar copia personal</button></div>${saved.activeRun?`<div class="note-banner"><strong>Hay un experimento en curso</strong><br>${e(saved.activeRun.name)}<button class="button small" data-nav="run" style="margin:10px 0 0 15px">Reanudar</button></div>`:''}<div class="section-heading"><h2>Experimentos y cálculos</h2><span>${saved.runs.length} registros</span></div>${saved.runs.length?saved.runs.slice().reverse().map(r=>`<article class="panel journal-entry"><div class="section-heading"><h3>${e(r.name||r.title)}</h3><span class="tag">${r.kind==='calculation'?'Cálculo':r.complete?'Finalizado':'Registrado'}</span></div><small>${stamp(r.date)}</small><p style="margin-top:12px">${e(r.result||r.notes||'Sin observaciones adicionales.')}</p>${r.config?`<p class="help">${r.config.reactions} muestras${r.config.components.length?` · ${r.config.controls} controles · ${r.config.volume} µL/reacción`:''} · ${r.config.edited?'Configuración personalizada':'Configuración inicial'}</p>`:''}<button class="text-button" data-export-run="${e(r.id)}" style="margin-top:13px">Exportar registro JSON</button></article>`).join(''):empty('Tu primer experimento empieza aquí','Completa un protocolo o guarda un cálculo para crear un registro.')}<div class="section-heading" style="margin-top:30px"><h2>Notas de protocolos y medios</h2><span>${entries.length} notas</span></div>${entries.map(([id,t])=>{const isMedia=id.startsWith('media:'),title=isMedia?media.find(m=>m.id===id.slice(6))?.name:allProtocols().find(p=>p.id===id)?.title;return `<article class="panel journal-entry"><div class="section-heading"><h3>${e(title||id)}</h3>${isMedia?`<button class="text-button" data-medium="${e(id.slice(6))}">Editar</button>`:`<button class="text-button" data-protocol="${e(id)}" data-notes-link>Editar</button>`}</div><p>${e(t)}</p></article>`;}).join('')||'<p class="help">Aún no has añadido notas.</p>'}`;}
function sourcesPage(){return heading('UN CATÁLOGO CON PROCEDENCIA','Fuentes y cobertura','Documentos originales, estado de revisión y acceso a los fabricantes.')+`<div class="note-banner"><strong>Catálogo inicial, no exhaustivo.</strong> ${baseProtocols.length} fichas, ${baseProtocols.filter(p=>p.status==='reviewed').length} con pasos revisados y ${media.length} referencias de medios. Las fichas Web son enlaces localizados; las fichas PDF identifican un documento. Fecha de revisión: 01/10/2026. Los parámetros extraídos se revisan antes de activar cálculos y ejecución.</div>${indexReport?`<div class="note-banner"><strong>Última indexación automática · ${stamp(indexReport.generatedAt)}</strong><br>${indexReport.documents.length} enlaces procesados · ${indexReport.documents.filter(d=>d.status==='verified-link').length} recuperados · ${indexReport.documents.filter(d=>d.documentType==='PDF').length} PDFs descargados para revisión. Algunos fabricantes restringen el acceso automatizado; la comprobación manual y la recuperación automática se registran por separado.</div>`:''}<div class="source-grid">${sources.map(v=>{const ps=baseProtocols.filter(p=>p.manufacturer===v.id),ms=media.filter(m=>m.manufacturer===v.id);return `<section class="panel source-card">${vendorIcon(v)}<h3>${e(v.name)}</h3><p>${ps.length} fichas · ${ps.filter(p=>p.status==='reviewed').length} con pasos<br>${ms.length} referencias de medios</p><a class="button small" href="${safeURL(v.url)}" target="_blank" rel="noopener noreferrer">Fuente oficial ${icon('external')}</a></section>`;}).join('')}</div><div class="two-col" style="margin-top:24px"><section class="panel"><h2>Ampliar la biblioteca</h2><p>Crea adaptaciones personales con pasos, tiempos y condiciones. Importa y exporta copias para compartirlas entre tus dispositivos.</p><button class="button" id="new-protocol">${icon('plus')}Nuevo protocolo</button></section><section class="panel"><h2>Indexación y revisión</h2><p>El repositorio incluye un indexador de documentos oficiales. Recoge metadatos, enlaces y huellas de los PDFs; los documentos nuevos quedan pendientes de revisión.</p><a href="https://github.com/camilo31-svg/molab-studio" target="_blank" rel="noopener noreferrer" class="small-link">Código e instrucciones en GitHub</a><p class="help">Los PDFs permanecen en su fuente original. No se republican manuales completos. La app no afirma cubrir todos los fabricantes ni todas las bases de datos.</p></section></div>`;}
function showDialog(body){$('#modal').innerHTML=`<div class="modal-heading"><span class="eyebrow" style="margin:0">MOLAB · ESPACIO PERSONAL</span><button class="icon-button" id="close-modal" aria-label="Cerrar">${icon('close')}</button></div>${body}`;$('#close-modal').onclick=()=>$('#modal').close();$('#modal').showModal();}
function newCompound(){showDialog(`<h2>Añadir compuesto</h2><p class="help" style="margin:10px 0 20px">Indica la sal e hidratación exactas.</p><form id="compound-form"><div class="form-grid"><label class="field full">Nombre<input id="compound-name" required maxlength="120" placeholder="Ej.: MgSO₄ heptahidrato"></label><label class="field">Fórmula / forma química<input id="compound-formula" required maxlength="120"></label>${numberField('Masa molecular (g/mol)','compound-mw',246.47)}</div><div id="compound-error"></div><div class="modal-footer"><button class="button primary" type="submit">Guardar en favoritos</button></div></form>`);$('#compound-form').onsubmit=ev=>{ev.preventDefault();try{const c={id:'compound-'+crypto.randomUUID(),name:$('#compound-name').value.trim(),formula:$('#compound-formula').value.trim(),mw:positive($('#compound-mw').value,'Masa molecular')};saved.customCompounds.push(c);saved.compoundFavorites.push(c.id);state.compound=c.id;persist();$('#modal').close();render();toast('Compuesto añadido.');}catch(err){$('#compound-error').innerHTML=`<p class="error">${e(err.message)}</p>`;}};}
function newProtocol(adapt){showDialog(`<h2>${adapt?'Adaptación personal':'Nuevo protocolo personal'}</h2><p class="help" style="margin:10px 0 18px">Una línea por paso: título | instrucciones | segundos | condiciones.</p><form id="protocol-form"><div class="form-grid"><label class="field full">Nombre<input id="new-title" required maxlength="160" value="${e(adapt?adapt.title+' · mi adaptación':'')}"></label><label class="field">Técnica<input id="new-category" required maxlength="80" value="${e(adapt?.category||'PCR')}"></label><label class="field">URL de la fuente<input id="new-source" type="url" value="${e(adapt?.source||'')}"></label><label class="field full">Descripción<textarea id="new-description" required style="min-height:70px">${e(adapt?.description||'')}</textarea></label><label class="field full">Pasos<textarea id="new-steps" required placeholder="Preparación | Mezclar reactivos | 0 | Hielo\nIncubación | Incubar la mezcla | 600 | 37 °C"></textarea></label><label class="field full">Reactivos opcionales (una línea: nombre | µL | molde si va aparte)<textarea id="new-components" style="min-height:90px" placeholder="Buffer 10X | 2.5\nDNA | 1 | molde"></textarea></label>${numberField('Volumen final (µL)','new-volume',25)}</div><div id="new-protocol-error"></div><div class="modal-footer"><button class="button primary" type="submit">Guardar protocolo</button></div></form>`);$('#protocol-form').onsubmit=ev=>{ev.preventDefault();try{const steps=$('#new-steps').value.split('\n').filter(l=>l.trim()).map(l=>{const [title,text,sec='0',conditions='']=l.split('|').map(x=>x.trim());if(!title||!text)throw new Error('Cada paso necesita título e instrucciones separados por |.');const seconds=Number(sec);if(!Number.isFinite(seconds)||seconds<0)throw new Error('Cada duración debe ser un número de segundos positivo o cero.');return {title,text,seconds,conditions};});if(!steps.length)throw new Error('Añade al menos un paso.');const components=$('#new-components').value.split('\n').filter(l=>l.trim()).map(l=>{const [name,v,flag]=l.split('|').map(x=>x.trim());if(!name||!Number.isFinite(Number(v))||Number(v)<0)throw new Error('Formato de reactivo: nombre | volumen no negativo.');return{name,volume:Number(v),template:flag==='molde'};});const p={id:'personal-'+crypto.randomUUID(),title:$('#new-title').value.trim(),manufacturer:'personal',category:$('#new-category').value.trim(),subtitle:'Protocolo personal',description:$('#new-description').value.trim(),mechanism:'Procedimiento personalizado; fundamento según tu documentación.',source:$('#new-source').value,sourceType:'fuente',status:'personal',version:'Adaptación personal',pages:'Personal',tags:[$('#new-category').value.trim()],steps,tips:[],volume:positive($('#new-volume').value,'Volumen'),...(components.length?{components}:{})};if(components.length)masterMix(initialConfig(p),components);saved.customProtocols.push(p);persist();$('#modal').close();state.detailTab='overview';location.hash='detail/'+p.id;toast('Protocolo personal guardado.');}catch(err){$('#new-protocol-error').innerHTML=`<p class="error">${e(err.message)}</p>`;}};}
function editSteps(p){const c=clone(configFor(p));showDialog(`<h2>Editar pasos y condiciones</h2><p class="help" style="margin:10px 0 20px">Se guarda una configuración personal; la fuente original se conserva.</p><div id="step-edit-list">${c.steps.map((s,i)=>`<div class="panel" style="padding:16px;margin-bottom:12px"><label class="field">Paso ${i+1} · título<input data-step="${i}" data-step-field="title" value="${e(s.title)}"></label><label class="field" style="margin:10px 0">Instrucciones<textarea style="min-height:65px" data-step="${i}" data-step-field="text">${e(s.text)}</textarea></label><div class="form-grid"><label class="field">Duración (segundos)<input type="number" min="0" data-step="${i}" data-step-field="seconds" value="${s.seconds}"></label><label class="field">Condiciones<input data-step="${i}" data-step-field="conditions" value="${e(s.conditions)}"></label></div></div>`).join('')}</div><div id="steps-error"></div><div class="modal-footer"><button class="button primary" id="save-steps">Guardar cambios</button></div>`);$('#save-steps').onclick=()=>{try{$$('[data-step]').forEach(el=>{const v=el.dataset.stepField==='seconds'?Number(el.value):el.value;if(el.dataset.stepField==='seconds'&&(!Number.isFinite(v)||v<0))throw new Error('La duración debe ser no negativa.');if(['title','text'].includes(el.dataset.stepField)&&!v.trim())throw new Error('Título e instrucciones no pueden estar vacíos.');c.steps[Number(el.dataset.step)][el.dataset.stepField]=v;});c.edited=true;saved.configs[p.id]=c;persist();$('#modal').close();render();toast('Pasos personalizados guardados.');}catch(err){$('#steps-error').innerHTML=`<p class="error">${e(err.message)}</p>`;}};}
function buildRunSteps(c){return c.steps.flatMap(s=>s.title==='Termociclado'&&c.thermal.length?expandThermal(c.thermal,c.cycles).map(t=>({title:t.label,text:t.cycle?`Ciclo ${t.cycle} de ${c.cycles}. ${s.text}`:s.text,conditions:`${t.temp} °C`,seconds:t.seconds,thermalPhase:true,repeat:!!t.repeat,cycle:t.cycle,perCycle:t.seconds})):clone(s));}
function startProtocol(p){try{if(saved.activeRun){showDialog(`<h2>Ya hay un experimento en curso</h2><p class="help">${e(saved.activeRun.name)}</p><div class="modal-footer"><button class="button primary" id="resume-current">Reanudar experimento</button></div>`);$('#resume-current').onclick=()=>{$('#modal').close();go('run');};return;}const c=clone(configFor(p));integer(c.reactions,'Muestras');if(c.components.length)masterMix(c,c.components);if(c.thermal.length)validateProgram(c.thermal,c.cycles);const steps=buildRunSteps(c);const name=$('#experiment-name').value.trim()||p.title; saved.activeRun={id:crypto.randomUUID(),protocolId:p.id,name,date:new Date().toISOString(),config:c,steps,index:0,notes:'',stepNotes:{},events:[],timer:{running:false,remaining:steps[0].seconds,deadline:null},source:p.source,version:p.version};persist();go('run');}catch(err){$('#config-error').innerHTML=`<p class="error">${e(err.message)}</p>`;}}
function runPage(){const r=saved.activeRun;if(!r)return empty('No hay un protocolo en marcha','Elige una ficha con pasos, revisa su configuración y pulsa Start.',`<button class="button primary" data-nav="protocols">Abrir protocolos</button>`);const step=r.steps[r.index];return `<div class="run-shell"><div class="run-top"><span>${e(r.name)}</span><button class="text-button" id="save-exit">Guardar y salir</button></div><div class="progress" aria-label="Progreso: ${r.index+1} de ${r.steps.length}"><div style="width:${(r.index+1)/r.steps.length*100}%"></div></div><section class="panel run-card"><p class="eyebrow">PASO ${r.index+1} DE ${r.steps.length}</p><h1>${e(step.title)}</h1><p>${e(step.text)}</p>${step.conditions?`<div class="run-condition">${icon('thermo')}${e(step.conditions)}</div>`:''}${step.thermalPhase?`<div class="note-banner">Fase del programa del equipo. ${step.repeat?`Ciclo ${step.cycle}/${r.config.cycles} · ${step.perCycle} s en esta fase.`:'Incubación única.'} Programa el ciclo completo en el equipo. La guía sigue las fases en su orden real; puedes avanzar según el estado del termociclador.</div>`:''}${step.seconds>0?`<div class="timer" id="run-timer">${timerText(currentRemaining())}</div><p class="timer-label" id="timer-label">${r.timer.running?'Cronómetro en marcha':'Cronómetro listo'}</p><div class="run-controls"><button class="button" id="timer-toggle">${r.timer.running?'Pausar':'Iniciar cronómetro'}</button><button class="button" id="timer-reset">Reiniciar</button></div>`:'<div class="note-banner">Sin duración fija. Continúa cuando completes este paso.</div>'}<label class="field run-note" style="text-align:left">Observaciones de este paso<textarea id="run-notes" placeholder="Condiciones reales, lote, incidencias…">${e(r.stepNotes[r.index]||'')}</textarea></label></section><div class="run-actions"><button class="button" id="previous-step" ${r.index===0?'disabled':''}>Paso anterior</button><button class="button primary" id="next-step">${r.index===r.steps.length-1?'Finalizar protocolo':'Siguiente paso'}</button></div><p class="help">Tu progreso se guarda en este navegador. Los temporizadores usan la hora de finalización para recuperar el tiempo tras volver a la app.</p></div>`;}
function timerText(s){s=Math.max(0,Math.ceil(s));let h=Math.floor(s/3600),m=Math.floor((s%3600)/60),sec=s%60;return (h?String(h).padStart(2,'0')+':':'')+String(m).padStart(2,'0')+':'+String(sec).padStart(2,'0');}
function currentRemaining(){const t=saved.activeRun?.timer;return t?t.running?Math.max(0,(t.deadline-Date.now())/1000):t.remaining:0;}
function startTick(){clearInterval(timerInterval);timerInterval=setInterval(()=>{if(!saved.activeRun)return;const remaining=currentRemaining(),el=$('#run-timer');if(el){el.textContent=timerText(remaining);el.classList.toggle('finished',remaining===0);}if(saved.activeRun.timer.running&&remaining===0){saved.activeRun.timer={running:false,remaining:0,deadline:null};persist();if($('#timer-label'))$('#timer-label').textContent='Tiempo finalizado';if($('#timer-toggle'))$('#timer-toggle').textContent='Tiempo finalizado';if(navigator.vibrate)navigator.vibrate([150,80,150]);toast('Tiempo del paso finalizado.');}},250);}
function saveRunNote(){const r=saved.activeRun;if(r&&$('#run-notes')){r.stepNotes[r.index]=$('#run-notes').value;persist();}}
function advance(direction){saveRunNote();const r=saved.activeRun;if(direction>0){r.events.push({step:r.index,title:r.steps[r.index].title,date:new Date().toISOString(),remaining:currentRemaining(),skippedTimer:currentRemaining()>0});}if(direction>0&&r.index===r.steps.length-1){const record={...r,complete:true,finishedAt:new Date().toISOString(),notes:Object.entries(r.stepNotes).filter(([,s])=>s.trim()).map(([i,t])=>`${r.steps[Number(i)].title}: ${t}`).join('\n\n')};saved.runs.push(record);saved.activeRun=null;persist();clearInterval(timerInterval);$('#app').innerHTML=`<div class="run-shell"><section class="panel run-card"><div class="finish-icon">${icon('check')}</div><p class="eyebrow">EXPERIMENTO REGISTRADO</p><h1>Protocolo completado</h1><p>${e(record.name)}</p><p class="help" style="margin-top:18px">Configuración, pasos, notas y horarios guardados en tu cuaderno.</p><div class="run-controls"><button class="button primary" data-nav="notebook">Ver registro</button><button class="button" data-export-run="${record.id}">Exportar JSON</button></div></section></div>`;bindView();return;}r.index+=direction;r.timer={running:false,remaining:r.steps[r.index].seconds,deadline:null};persist();render();}
function download(name,content,type='application/json'){const u=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function attachCommon(){ $('[data-export-data]').forEach(b=>b.onclick=()=>$('#backup').click());$('[data-import-data]').forEach(b=>b.onclick=()=>$('#restore').click()); $$('[data-nav]').forEach(b=>b.onclick=()=>go(b.dataset.nav));$$('[data-protocol]').forEach(b=>b.onclick=()=>{state.detailTab=b.hasAttribute('data-notes-link')?'notes':'overview';location.hash='detail/'+b.dataset.protocol;});$$('[data-favorite]').forEach(b=>b.onclick=()=>{const prop=b.dataset.type==='media'?'mediaFavorites':'favorites',id=b.dataset.favorite;saved[prop]=saved[prop].includes(id)?saved[prop].filter(x=>x!==id):[...saved[prop],id];persist();render();});$$('[data-calc]').forEach(b=>b.onclick=()=>{state.calc=b.dataset.calc;if(state.page==='calculators')render();else go('calculators');});$$('[data-compound]').forEach(b=>b.onclick=()=>{state.compound=b.dataset.compound;state.calc='solutions';if(state.page==='calculators')render();else go('calculators');});$$('[data-compound-star]').forEach(b=>b.onclick=()=>{const id=b.dataset.compoundStar;saved.compoundFavorites=saved.compoundFavorites.filter(x=>x!==id);persist();render();});$$('[data-medium]').forEach(b=>b.onclick=()=>mediumDialog(b.dataset.medium));$$('[data-print]').forEach(b=>b.onclick=()=>window.print());$$('[data-export-run]').forEach(b=>b.onclick=()=>{const r=saved.runs.find(r=>r.id===b.dataset.exportRun);download('molab-registro-'+r.id+'.json',JSON.stringify(r,null,2));});if($('#new-protocol'))$('#new-protocol').onclick=()=>newProtocol();}
function bindView(){attachCommon();if(state.page==='protocols'){$$('[data-view]').forEach(b=>b.onclick=()=>{state.view=b.dataset.view;render();});$$('[data-category]').forEach(b=>b.onclick=()=>{state.category=b.dataset.category;render();});$('#ready-filter').onchange=ev=>{state.onlyReady=ev.target.checked;render();};$('#protocol-search').oninput=ev=>{state.query=ev.target.value;const pos=ev.target.selectionStart;render();$('#protocol-search').focus();$('#protocol-search').setSelectionRange(pos,pos);};}
 if(state.page==='detail'){const p=getProtocol();if(!p)return;$$('[data-tab]').forEach(b=>b.onclick=()=>{state.detailTab=b.dataset.tab;render();});if($('#save-note'))$('#save-note').onclick=()=>{saved.notes[p.id]=$('#protocol-note').value;persist();toast('Notas guardadas.');};if($('#adapt-protocol'))$('#adapt-protocol').onclick=()=>newProtocol(p);if(state.detailTab==='config'){const update=ev=>{let c=clone(configFor(p));if(ev.target.dataset.config==='volume'){const next=Number(ev.target.value);if(next>0&&c.volume>0){const factor=next/c.volume; c.components.forEach((r,i)=>{if(!r.template){r.volume=Math.round(r.volume*factor*100000)/100000;const input=document.querySelector(`[data-component="${i}"]`);if(input)input.value=r.volume;}});}}$$('[data-config]').forEach(x=>c[x.dataset.config]=Number(x.value));$$('[data-component]').forEach(x=>c.components[Number(x.dataset.component)].volume=Number(x.value));$$('[data-thermal]').forEach(x=>c.thermal[Number(x.dataset.thermal)][x.dataset.field]=x.dataset.field==='repeat'?x.checked:Number(x.value));c.edited=true;saved.configs[p.id]=c;persist();if($('#mix-result'))try{$('#mix-result').innerHTML=mixTable(masterMix(c,c.components));}catch(err){$('#mix-result').innerHTML=`<p class="error">${e(err.message)}</p>`;}if($('#thermal-chart'))$('#thermal-chart').innerHTML=thermalChart(c.thermal);if($('#thermal-duration'))$('#thermal-duration').textContent=thermalDescription(c);};$$('[data-config],[data-component],[data-thermal]').forEach(x=>x.oninput=update);$('#edit-steps').onclick=()=>editSteps(p);$('#add-thermal').onclick=()=>addThermal(p);$('#reset-config').onclick=()=>{delete saved.configs[p.id];persist();render();};$('#start-protocol').onclick=()=>startProtocol(p);if($('#export-mix'))$('#export-mix').onclick=()=>{try{const m=masterMix(configFor(p),configFor(p).components),csv=['Reactivo,Por tubo (uL),Total (uL),Destino',...m.rows.map(r=>`"${r.name.replace(/"/g,'""')}",${r.per},${r.total},${r.template?'Por tubo':'Mezcla comun'}`)].join('\r\n');download('molab-mastermix.csv','\uFEFF'+csv,'text/csv;charset=utf-8');}catch(err){toast(err.message);}};}}
 if(state.page==='calculators'){$$('#app input,#app select').forEach(x=>x.oninput=updateCalc);if($('#compound-select'))$('#compound-select').onchange=ev=>{state.compound=ev.target.value;render();};if($('#save-compound'))$('#save-compound').onclick=()=>{const id=$('#compound-select').value;saved.compoundFavorites=saved.compoundFavorites.includes(id)?saved.compoundFavorites.filter(x=>x!==id):[...saved.compoundFavorites,id];persist();render();};if($('#new-compound'))$('#new-compound').onclick=newCompound;if($('#update-compound'))$('#update-compound').onclick=()=>{try{const c=allCompounds().find(c=>c.id===state.compound);const mw=positive($('#mw').value,'Masa molecular');if(c.id.startsWith('compound-')){saved.customCompounds.find(x=>x.id===c.id).mw=mw;}else {const copy={...c,id:'compound-'+crypto.randomUUID(),name:c.name+' · personal',mw};saved.customCompounds.push(copy);saved.compoundFavorites.push(copy.id);state.compound=copy.id;}persist();render();toast('Masa molecular personal guardada.');}catch(err){toast(err.message);}};$$('[data-mix-protocol]').forEach(b=>b.onclick=()=>{state.detailTab='config';location.hash='detail/'+b.dataset.mixProtocol;});if($('#record-calc'))$('#record-calc').onclick=()=>{if(!lastCalc){toast('Revisa los valores antes de guardar.');return;}saved.runs.push({id:crypto.randomUUID(),kind:'calculation',name:lastCalc.title,date:new Date().toISOString(),input:clone(lastCalc.input),result:lastCalc.result+'\n'+lastCalc.description,calculator:lastCalc.kind});persist();toast('Cálculo guardado en el cuaderno.');};updateCalc();}
 if(state.page==='media'){$$('[data-media-category]').forEach(b=>b.onclick=()=>{state.mediaCategory=b.dataset.mediaCategory;render();});$('#media-search').oninput=ev=>{state.mediaQuery=ev.target.value;const pos=ev.target.selectionStart;render();$('#media-search').focus();$('#media-search').setSelectionRange(pos,pos);};}
 if(state.page==='run'&&saved.activeRun){$('#run-notes').oninput=saveRunNote;$('#save-exit').onclick=()=>{saveRunNote();go('notebook');};$('#previous-step').onclick=()=>advance(-1);$('#next-step').onclick=()=>advance(1);if($('#timer-toggle'))$('#timer-toggle').onclick=()=>{const r=saved.activeRun;if(r.timer.running)r.timer={running:false,remaining:currentRemaining(),deadline:null};else if(r.timer.remaining>0)r.timer={running:true,remaining:r.timer.remaining,deadline:Date.now()+r.timer.remaining*1000};persist();render();};if($('#timer-reset'))$('#timer-reset').onclick=()=>{saved.activeRun.timer={running:false,remaining:saved.activeRun.steps[saved.activeRun.index].seconds,deadline:null};persist();render();};}
}
$('#backup').onclick=()=>download('molab-copia-personal.json',JSON.stringify({format:'molab-v1',exportedAt:new Date().toISOString(),data:saved},null,2));
$('#restore').onchange=async ev=>{const file=ev.target.files[0];if(!file)return;try{if(file.size>5000000)throw new Error('La copia supera 5 MB.');const data=JSON.parse(await file.text());validateBackup(data);showDialog(`<h2>Importar copia personal</h2><p class="help">Se reemplazarán los datos locales de este navegador: favoritos, notas, protocolos personales y registros. Puedes exportar tus datos actuales antes de continuar.</p><div class="modal-footer"><button class="button" id="backup-current">Exportar datos actuales</button><button class="button primary" id="confirm-import">Importar copia</button></div>`);$('#backup-current').onclick=()=>$('#backup').click();$('#confirm-import').onclick=()=>{saved={...blank(),...data.data};persist();$('#modal').close();render();toast('Copia importada.');};}catch(err){toast('No se pudo importar: '+err.message);}ev.target.value='';};
function validateBackup(x){if(x.format!=='molab-v1'||!x.data||typeof x.data!=='object')throw new Error('Formato no reconocido.');for(const k of ['favorites','compoundFavorites','mediaFavorites','customCompounds','customProtocols','runs'])if(!Array.isArray(x.data[k]))throw new Error('Copia incompleta: '+k);for(const k of ['notes','configs'])if(!x.data[k]||Array.isArray(x.data[k])||typeof x.data[k]!=='object')throw new Error('Campo incorrecto: '+k);for(const note of Object.values(x.data.notes))if(typeof note!=='string')throw new Error('Notas inválidas.');for(const p of x.data.customProtocols){if(!p.id||!p.title||!p.category||!Array.isArray(p.steps)||!Array.isArray(p.tags)||!Array.isArray(p.tips))throw new Error('Protocolo personal inválido.');for(const s of p.steps)if(!s.title||!s.text||!Number.isFinite(s.seconds)||s.seconds<0)throw new Error('Paso inválido.');}for(const c of x.data.customCompounds)if(!c.id||!c.name||!c.formula||!Number.isFinite(c.mw)||c.mw<=0)throw new Error('Compuesto inválido.');for(const c of Object.values(x.data.configs))if(!Array.isArray(c.steps)||!Array.isArray(c.components)||!Array.isArray(c.thermal))throw new Error('Configuración inválida.');if(x.data.activeRun&&(!Array.isArray(x.data.activeRun.steps)||!x.data.activeRun.timer||!Number.isInteger(x.data.activeRun.index)||x.data.activeRun.index<0||x.data.activeRun.index>=x.data.activeRun.steps.length))throw new Error('Experimento activo inválido.');}
document.addEventListener('keydown',ev=>{if((ev.ctrlKey||ev.metaKey)&&ev.key==='k'){ev.preventDefault();if(state.page!=='protocols'){location.hash='protocols';setTimeout(()=>$('#protocol-search')?.focus(),100);}else $('#protocol-search').focus();}});
window.addEventListener('hashchange',readRoute);readRoute();
fetch('./catalog-index.json').then(r=>{if(!r.ok)throw new Error('Index not available');return r.json();}).then(data=>{indexReport=data;if(state.page==='sources')render();}).catch(()=>{});
if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});

function addThermal(p){showDialog(`<h2>Añadir fase térmica</h2><form id="thermal-form"><div class="form-grid"><label class="field full">Nombre de la fase<input id="phase-label" required maxlength="80" value="Incubación"></label>${numberField('Temperatura (°C)','phase-temp',37,0)}${numberField('Duración (segundos)','phase-seconds',600,0)}<label class="checkbox-field full"><input id="phase-repeat" type="checkbox">Repetir en cada ciclo</label></div><div id="phase-error"></div><div class="modal-footer"><button class="button primary">Añadir fase</button></div></form>`);$('#thermal-form').onsubmit=ev=>{ev.preventDefault();try{const c=clone(configFor(p)),phase={label:$('#phase-label').value.trim(),temp:Number($('#phase-temp').value),seconds:Number($('#phase-seconds').value),repeat:$('#phase-repeat').checked};validateProgram([phase],c.cycles);c.thermal.push(phase);if(!c.steps.some(s=>s.title==='Termociclado'))c.steps.push({title:'Termociclado',text:'Ejecuta el programa térmico personalizado en el equipo.',conditions:'Programa personal',seconds:0});c.edited=true;saved.configs[p.id]=c;persist();$('#modal').close();render();}catch(err){$('#phase-error').innerHTML=`<p class="error">${e(err.message)}</p>`;}};}
